\centering
\small
\caption{Training hyperparameters for all configurations. Effective batch size is $\text{per-device} \times \text{grad.\ accum.} = 32$ in all cases.}
\label{tab:hyperparams}
\setlength{\tabcolsep}{3pt}
\begin{tabular}{lcccc}
\toprule
\textbf{Hyperparameter} & \textbf{4B \cls{}} & \textbf{4B \cwm{}} & \textbf{8B \cls{}} & \textbf{8B \cwm{}} \\
\midrule
Base model & Qwen3-4B & Qwen3-4B & Qwen3-8B & Qwen3-8B \\
